use std::fs

fn digit_val(c: char) -> int {
    let d = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    let mut i = 0
    for x in d.chars() {
        if x == c.to_ascii_uppercase() {
            return i
        }
        i += 1
    }
    0
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let digits: Vec<char> = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ".chars().collect()
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() < 3 {
            continue
        }
        let from = parts[1].parse::<int>().unwrap_or(10)
        let to: int = parts[2].parse::<int>().unwrap_or(10)
        let mut n: int = 0
        for c in parts[0].chars() {
            n = n * from + digit_val(c)
        }
        if n == 0 {
            println("0")
            continue
        }
        let mut out: Vec<char> = []
        while n > 0 {
            let r: int = n % to
            out.push(digits[r])
            n = n / to
        }
        out.reverse()
        let mut s = ""
        for c in out {
            s = s + c.to_string()
        }
        println(s)
    }
}

